insert into public.app_pages (game_id, page_key, title, short, icon, tint, blurb, position) values
  ('fortunes-weave', 'units', 'Units', 'Units', 'Users', 'berry', 'Who can join your army, how to recruit them, and who''s worth a spot.', 0),
  ('fortunes-weave', 'party', 'Party', 'Party', 'ClipboardList', 'slate', 'Your own party for this run, and the next step for each of them.', 1),
  ('fortunes-weave', 'classes', 'Classes', 'Classes', 'Shield', 'indigo', 'Every class, its tier, and how to reach it.', 2),
  ('fortunes-weave', 'items', 'Items', 'Items', 'Backpack', 'sun', 'Key items, materials, weapons and magic: where to find them and how they compare.', 3),
  ('fortunes-weave', 'last-chances', 'Last chances', 'Last chances', 'Hourglass', 'plum', 'Things you can miss forever, and the deadline for each. Tick them off as you go.', 4),
  ('fortunes-weave', 'story', 'Story', 'Story', 'Flag', 'sky', 'The parts of the story in order, kept spoiler-light.', 5),
  ('fortunes-weave', 'world', 'World', 'World', 'MapPin', 'teal', 'Dungeons and places worth visiting, and the foes waiting in them.', 6),
  ('fortunes-weave', 'guides', 'Guides', 'Guides', 'BookOpen', 'leaf', 'How the game''s systems work, and the questions nobody has answered yet.', 7)
insert into public.game_blocks (game_id, block_key, title, position, page_key, type, look, icon, intro, filters, by_route, stat_name, stats, symbols, fields, tier_setup, plan_setup) values
  ('fortunes-weave', 'units', 'Units', 0, 'units', 'characters', null, 'Users', 'Pick your Flame Lord to see who can join you and what it takes.', array['Group']::text[], true, null, '[{"key":"hp","label":"HP","better":"high"},{"key":"str","label":"Str","better":"high"},{"key":"mag","label":"Mag","better":"high"},{"key":"spd","label":"Spd","better":"high"},{"key":"dex","label":"Dex","better":"high"},{"key":"def","label":"Def","better":"high"},{"key":"res","label":"Res","better":"high"},{"key":"lck","label":"Lck","better":"high"},{"key":"cha","label":"Cha","better":"high"}]'::jsonb, '{"Promised One''s Army":"Star","Ribeira Winds":"Wind","House Lamine":"Castle","Megaira''s Beacon":"Lighthouse","Rose Tempest":"Flower2","Fiery Mane":"Flame","Tale of the Moon":"Moon","Linaria Dewdrops":"Droplet","Bridal Party of the Pale Raven":"Bird","Kingdom of Arago":"Crown","Clan leader":"Tent","Temple Army":"Landmark","Unaffiliated":"Compass"}'::jsonb, '[{"key":"Group","label":"Group","kind":"tag"},{"key":"Playable","label":"Playable or NPC","kind":"playable","off":true},{"key":"@tier","label":"Community tier","kind":"tier"},{"key":"Age","label":"Age","kind":"text","beside":true},{"key":"Role or class","label":"Role or class","kind":"tag"},{"key":"Location","label":"Location","kind":"place"},{"key":"Time of arrival","label":"Time of arrival","kind":"when"},{"key":"@stats","label":"Stat growths","kind":"chart"},{"key":"Skills","label":"Skills","kind":"list"},{"key":"@description","label":"Description","kind":"longtext"},{"key":"Recruit","label":"How to recruit","kind":"longtext"},{"key":"Relationships","label":"Relationships","kind":"links"},{"key":"Likes","label":"Likes and gifts","kind":"list","off":false}]'::jsonb, null, null),
  ('fortunes-weave', 'unit-tiers', 'Unit tiers', 1, 'units', 'tierlist', null, 'Trophy', 'Who''s worth a spot in your army, across the whole game? Rank them in My list, and the community list is everyone''s lists together.', array[]::text[], false, null, null, null, null, '{"ranks":"units","tiers":[{"key":"s","label":"S"},{"key":"a","label":"A"},{"key":"b","label":"B"},{"key":"c","label":"C"},{"key":"d","label":"D"}]}'::jsonb, null),
  ('fortunes-weave', 'your-party', 'Your party', 2, 'party', 'planner', null, 'ClipboardList', 'Pick who you’ll take. Each one shows what to do next to get them.', array[]::text[], true, null, null, null, null, null, '{"roster":"units","size":15,"unlock":["Recruit","@description"],"classes":"classes","slots":[{"key":"weapons","label":"Weapons and magic","from":"weapons-and-magic","count":3}]}'::jsonb),
  ('fortunes-weave', 'classes', 'Classes', 3, 'classes', 'classes', null, 'Shield', 'Climb the ladder: a tier’s License and exam open its classes. Tap a tier for what it takes, or a class for its exam, skills and growths.', array['Tier', 'Moves']::text[], false, null, '[{"key":"hp","label":"HP","better":"high"},{"key":"str","label":"Str","better":"high"},{"key":"mag","label":"Mag","better":"high"},{"key":"spd","label":"Spd","better":"high"},{"key":"dex","label":"Dex","better":"high"},{"key":"def","label":"Def","better":"high"},{"key":"res","label":"Res","better":"high"},{"key":"lck","label":"Lck","better":"high"},{"key":"cha","label":"Cha","better":"high"}]'::jsonb, null, '[{"key":"Tier","label":"Tier","kind":"tag","choices":[{"name":"Beginner","about":"Level 5 · Renown 1 · Beginner License\nEvery unit''s first step. Each class''s mastery skill adds +1 to its main stats."},{"name":"Specialty","about":"Level 20 · Renown 4 · Specialty License\nTwelve classes, none of them secret."},{"name":"Advanced","about":"Level 35 · Renown 8 · Advanced License\nEight open to everyone, nine more locked to a route, a quest or Part III. A class unlocked on one route opens on every route."},{"name":"Master","about":"Level 45 · Part III\nUnlocked in Part III. Six of them need a god’s temple restored first."},{"name":"Divine","about":"Part III, fourth section · the five Keys of the Diadem\nOpened at the Diadem Temple. The exam needs S ranks and a 100% pass chance, and only one unit can hold each Divine class at a time."}]},{"key":"Moves","label":"Moves","kind":"tag"},{"key":"@tier","label":"Community tier","kind":"tier","off":true},{"key":"@stats","label":"Growth modifiers","kind":"chart","noWeb":true},{"key":"Exam needs","label":"Exam needs","kind":"list"},{"key":"Leads to","label":"Leads to","kind":"links"},{"key":"How to unlock","label":"How to unlock","kind":"longtext"},{"key":"Who can take it","label":"Who can take it","kind":"text"},{"key":"Mastery skill","label":"Mastery skill","kind":"list"},{"key":"Skills","label":"Skills","kind":"list"},{"key":"@description","label":"Description","kind":"longtext"}]'::jsonb, null, null),
  ('fortunes-weave', 'items', 'Items', 4, 'items', 'items', null, 'Backpack', 'What each one is for and where to find it. Tap one for the details.', array['Type']::text[], false, null, null, '{"Key item":"KeyRound","Material":"Wheat","Quest item":"ScrollText","License":"BadgeCheck","Resource":"Sparkles","Equipment":"Gem","Shield":"Shield","Consumable":"FlaskConical","Spell scroll":"Scroll","Crate":"Package","Gift":"Gift"}'::jsonb, '[{"key":"Type","label":"Type","kind":"tag"},{"key":"@tier","label":"Community tier","kind":"tier","off":true},{"key":"Rank","label":"Rank or rarity","kind":"tag","off":true,"tile":true},{"key":"Price","label":"Price","kind":"number","off":true,"tile":true},{"key":"Sell price","label":"Sell price","kind":"number","off":true},{"key":"@stats","label":"Stats","kind":"chart","off":true,"tile":true,"noWeb":true},{"key":"Used for","label":"Used for","kind":"longtext"},{"key":"Where to get it","label":"Where to get it","kind":"list"},{"key":"Made from","label":"Made from","kind":"links"},{"key":"Upgrades to","label":"Upgrades to","kind":"links","off":true},{"key":"Who can use it","label":"Who can use it","kind":"text","off":true},{"key":"@description","label":"Description","kind":"longtext","off":true}]'::jsonb, null, null),
  ('fortunes-weave', 'weapons-and-magic', 'Weapons and magic', 5, 'items', 'items', null, 'Swords', 'The stronger the color, the better the number. Compare puts every number side by side.', array['Weapon type', 'Rank']::text[], false, null, '[{"key":"might","label":"Might","better":"high"},{"key":"hit","label":"Hit","better":"high"},{"key":"weight","label":"Weight","better":"low"},{"key":"crit","label":"Crit","better":"high"}]'::jsonb, '{"Sword":"Sword","Spear":"Spear","Axe":"Axe","Bow":"BowArrow","Gauntlet":"HandFist","Black Magic":"WandSparkles","White Magic":"Sun"}'::jsonb, '[{"key":"Rank","label":"Rank","kind":"tag","tile":true},{"key":"Weapon type","label":"Weapon type","kind":"tag"},{"key":"@stats","label":"Stats","kind":"chart","tile":true,"noWeb":true},{"key":"Effect","label":"What it does","kind":"longtext"},{"key":"Note","label":"Note","kind":"longtext"},{"key":"Where to get it","label":"Where to get it","kind":"list"},{"key":"Used for","label":"Used for","kind":"longtext"},{"key":"Type","label":"Type","kind":"tag","off":true},{"key":"@tier","label":"Community tier","kind":"tier","off":true},{"key":"Price","label":"Price","kind":"number","off":true,"tile":true},{"key":"Sell price","label":"Sell price","kind":"number","off":true},{"key":"Made from","label":"Made from","kind":"links","off":true},{"key":"Upgrades to","label":"Upgrades to","kind":"links","off":true},{"key":"Who can use it","label":"Who can use it","kind":"text","off":true},{"key":"@description","label":"Description","kind":"longtext","off":true}]'::jsonb, null, null),
